window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6ac02a2f663f30d0"]={"versions": [{"id": "FIG-6ac02a2f663f30d0", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von C++-spezifischen Eigenschaften von Datentypen im Kontext der AUTOSAR Adaptive Platform (AUTOSAR_TPS_ManifestSpecification, C++-specific properties of ImplementationDataType). Das Diagramm modelliert die M2-Metamodell-Struktur für Implementierungsdatentypen, deren strukturelle Unterelemente, Namensraum-Zugehörigkeiten über Symbol-Definitionen sowie Erweiterungsmechanismen für Allokatoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataType</strong> (spezialisiert <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AutosarDataType</code>): Repräsentiert den konkreten Implementierungsdatentyp. Attribute:</li>\n<li><code>dynamicArraySizeProfile : String [0..1]</code></li>\n<li><code>typeEmitter : NameToken [0..1]</code></li>\n<li>Assoziationen / Kompositionen:</li>\n<li><code>+symbolProps</code> (Stereotyp «atpSplitable»): Aggregation/Komposition von <code>0..1</code> <code>SymbolProps</code>.</li>\n<li><code>+subElement</code> (Stereotyp «atpVariation»): Geordnete Komposition von <code>0..* {ordered}</code> <code>ImplementationDataTypeElement</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeElement</strong> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>): Repräsentiert Unterelemente eines strukturierten Datentyps. Attribute:</li>\n<li><code>arraySizeHandling : ArraySizeHandlingEnum [0..1]</code></li>\n<li><code>arraySizeSemantics : ArraySizeSemanticsEnum [0..1]</code></li>\n<li><code>«atpVariation» + arraySize : PositiveInteger [0..1]</code></li>\n<li>Assoziationen / Kompositionen:</li>\n<li>Rekursive Komposition <code>+subElement</code> (Stereotyp «atpVariation»): <code>0..* {ordered}</code> geschachtelte <code>ImplementationDataTypeElement</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeExtension</strong> (spezialisiert <code>ARElement</code>):</li>\n<li>Referenziert über gerichtete Assoziation <code>+implementationDataType</code> genau <code>1</code> <code>ImplementationDataType</code>.</li>\n<li>Besitzt über Komposition <code>+namespace</code> eine geordnete Liste von <code>0..* {ordered}</code> <code>SymbolProps</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeElementExtension</strong> (spezialisiert <code>ARElement</code>):</li>\n<li>Referenziert über gerichtete Assoziation <code>+implementationDataTypeElement</code> genau <code>1</code> <code>ImplementationDataTypeElement</code>.</li>\n<li>Referenziert über Assoziation <code>+allocator</code> optional <code>0..1</code> <code>Allocator</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Allocator</strong> (spezialisiert <code>ARElement</code>): Modelliert die Speicherallokations-Entität für Datentypelemente.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>SymbolProps</strong> (spezialisiert <code>ImplementationProps</code>, welches <code>Referrable</code> spezialisiert):</li>\n<li>Attribut: <code>+ symbol : CIdentifier</code>.</li>\n<li>Dient als Namensraum- und Symbolspezifikation für C++-Bezeichner.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell beschreibt eine statische Definitionsstruktur ohne dynamische Laufzeitsequenzen. Variabilitäten über das Tag <code>vh.latestBindingTime = preCompileTime</code> an den mit <code>«atpVariation»</code> annotierten Assoziationen und Attributen steuern die Auswertung zur Vorkompilierungszeit (Pre-Compile Time). Strukturierte Typen werden hierarchisch über geschachtelte <code>subElement</code>-Beziehungen aufgelöst, während über <code>ImplementationDataTypeExtension</code> und <code>SymbolProps</code> die Generierung des C++-Zielnamensraums strukturiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bindungszeit für Variabilitäten (<code>«atpVariation»</code>) an <code>subElement</code> und <code>arraySize</code> ist strikt auf <code>preCompileTime</code> festgelegt.</li>\n<li><code>SymbolProps.symbol</code> ist als gültiger <code>CIdentifier</code> zu formulieren.</li>\n<li>Sequenzen von Namensräumen (<code>+namespace</code>) und Unterelementen (<code>+subElement</code>) sind als <code>{ordered}</code> definiert; die Reihenfolge in der Manifest-Instanziierung ist semantisch bindend für C++-Namensraumhierarchien und Struktur-Layouts.</li>\n<li><code>+symbolProps</code> an <code>ImplementationDataType</code> ist als <code>«atpSplitable»</code> gekennzeichnet, was ein Splitting über Manifest-Dateigrenzen hinweg erlaubt.</li>\n</ul>"}, {"id": "FIG-c86659456fe80e84", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von C++-spezifischen Eigenschaften von Datentypen im Kontext der AUTOSAR Adaptive Platform (AUTOSAR_TPS_ManifestSpecification, C++-specific properties of ImplementationDataType). Das Diagramm modelliert die M2-Metamodell-Struktur für Implementierungsdatentypen, deren strukturelle Unterelemente, Namensraum-Zugehörigkeiten über Symbol-Definitionen sowie Erweiterungsmechanismen für Allokatoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataType</strong> (spezialisiert <code>AbstractImplementationDataType</code>): Repräsentiert den Implementierungsdatentyp. Attribute:</li>\n<li><code>dynamicArraySizeProfile : String [0..1]</code></li>\n<li><code>typeEmitter : NameToken [0..1]</code></li>\n<li>Assoziationen / Kompositionen:</li>\n<li><code>+symbolProps</code> (Stereotyp «atpSplitable»): Aggregation/Komposition von <code>0..1</code> <code>SymbolProps</code>.</li>\n<li><code>+subElement</code> (Stereotyp «atpVariation»): Geordnete Komposition von <code>0..* {ordered}</code> <code>ImplementationDataTypeElement</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeElement</strong> (spezialisiert <code>AtpStructureElement</code>, <code>Identifiable</code>): Repräsentiert Unterelemente eines strukturierten Datentyps. Attribute:</li>\n<li><code>arraySizeHandling : ArraySizeHandlingEnum [0..1]</code></li>\n<li><code>arraySizeSemantics : ArraySizeSemanticsEnum [0..1]</code></li>\n<li><code>«atpVariation» + arraySize : PositiveInteger [0..1]</code></li>\n<li>Assoziationen / Kompositionen:</li>\n<li>Rekursive Komposition <code>+subElement</code> (Stereotyp «atpVariation»): <code>0..* {ordered}</code> geschachtelte <code>ImplementationDataTypeElement</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeExtension</strong> (spezialisiert <code>ARElement</code>):</li>\n<li>Referenziert über gerichtete Assoziation <code>+implementationDataType</code> genau <code>1</code> <code>ImplementationDataType</code>.</li>\n<li>Besitzt über Komposition <code>+namespace</code> eine geordnete Liste von <code>0..* {ordered}</code> <code>SymbolProps</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>ImplementationDataTypeElementExtension</strong> (spezialisiert <code>ARElement</code>):</li>\n<li>Referenziert über gerichtete Assoziation <code>+implementationDataTypeElement</code> genau <code>1</code> <code>ImplementationDataTypeElement</code>.</li>\n<li>Referenziert über Assoziation <code>+allocator</code> optional <code>0..1</code> <code>Allocator</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Allocator</strong> (spezialisiert <code>ARElement</code>):</li>\n<li>Besitzt über Komposition <code>+namespace</code> eine geordnete Liste von <code>0..* {ordered}</code> <code>SymbolProps</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>SymbolProps</strong> (spezialisiert <code>ImplementationProps</code>, welches <code>Referrable</code> spezialisiert):</li>\n<li>Attribut: <code>+ symbol : CIdentifier</code>.</li>\n<li>Dient als Namensraum- und Symbolspezifikation für C++-Bezeichner (<code>ImplementationDataTypeExtension</code>, <code>ImplementationDataType</code> und <code>Allocator</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell beschreibt eine statische Definitionsstruktur ohne dynamische Laufzeitsequenzen. Variabilitäten über das Tag <code>vh.latestBindingTime = preCompileTime</code> an den mit <code>«atpVariation»</code> annotierten Assoziationen und Attributen steuern die Auswertung zur Vorkompilierungszeit (Pre-Compile Time). Strukturierte Typen werden hierarchisch über geschachtelte <code>subElement</code>-Beziehungen aufgelöst, während über <code>ImplementationDataTypeExtension</code> und <code>SymbolProps</code> die Generierung des C++-Zielnamensraums strukturiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Bindungszeit für Variabilitäten (<code>«atpVariation»</code>) an <code>subElement</code> und <code>arraySize</code> ist strikt auf <code>preCompileTime</code> festgelegt.</li>\n<li><code>SymbolProps.symbol</code> ist als gültiger <code>CIdentifier</code> zu formulieren.</li>\n<li>Sequenzen von Namensräumen (<code>+namespace</code>) an <code>ImplementationDataTypeExtension</code> und <code>Allocator</code> sowie von Unterelementen (<code>+subElement</code>) sind als <code>{ordered}</code> definiert; die Reihenfolge in der Manifest-Instanziierung ist semantisch bindend für C++-Namensraumhierarchien und Struktur-Layouts.</li>\n<li><code>+symbolProps</code> an <code>ImplementationDataType</code> ist als <code>«atpSplitable»</code> gekennzeichnet, was ein Splitting über Manifest-Dateigrenzen hinweg erlaubt.</li>\n</ul>"}], "trans": [{"from": "FIG-6ac02a2f663f30d0", "to": "FIG-c86659456fe80e84", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>ImplementationDataType</strong>: Die Generalisierungen <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AutosarDataType</code> wurden durch die Spezialisierung von <code>AbstractImplementationDataType</code> ersetzt.</li>\n<li><strong>Allocator</strong>: Neue geordnete Kompositionsbeziehung <code>+namespace</code> (Kardinalität <code>0..* {ordered}</code>) von <code>Allocator</code> zu <code>SymbolProps</code>.</li>\n<li><strong>ImplementationDataType</strong>: Der Pfeilkopf der Assoziation <code>+implementationDataType</code> von <code>ImplementationDataTypeExtension</code> zeigt nun nach oben statt nach unten (gerichtete Assoziation/Referenz auf <code>ImplementationDataType</code>).</li>\n</ul>"}]};
